    let mut score = post_residual as f64;

    // 1. Penalty for creating "slivers" (unusable space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead optimization: If next_item_size is large, favor larger post_residuals
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize bins that cannot fit the next item if they are the only option
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward bins that can accommodate the next item (Best Fit Lookahead)
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    }

    // 3. Global State: Discourage opening new bins unless necessary
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if the average residual of existing bins is already very low
        // or if we have very few items left.
        let progress = step_index as f64 / total_items as f64;
        let threshold = 15.0 + (progress * 20.0);
        if mean_residual > threshold && fitting_bins_count > 0 {
            score += 200.0; // Strong penalty for new bin if existing bins are efficient
        }
    } else {
        // 4. Tightness bias: Favor bins that are already "half-full" to consolidate space
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill_ratio * 10.0;
    }

    // 5. Urgency: If this is the last chance to fit an item in an existing bin, reduce penalty
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
