pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that result in the smallest post_residual
    // This is already the base score.

    // 2. Harmonic Class Penalization:
    // Penalize post_residuals that are small but unusable (1..9), 
    // as they create "dead space" that cannot fit any further items (minimum size 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 3. Lookahead Synergy:
    // If we have a next item, favor bins where the post_residual can accommodate the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward: This bin becomes a candidate for the next item, reducing fragmentation.
            score -= 25.0;
        } else {
            // Penalty: If post_residual is not enough for the next item, we might be forced to open a new bin later.
            score += 10.0;
        }
    }

    // 4. New Bin Thresholding:
    // If this is an empty bin (bin_residual == bin_capacity), only open if the current fit is catastrophic.
    if bin_residual == bin_capacity {
        // Only consider a new bin if the mean_residual is already very low (bins are full)
        // or if we have very few bins open.
        score += 40.0; 
        if mean_residual < 20.0 {
            score -= 15.0;
        }
    }

    // 5. Fitting Context:
    // If this is the only bin that can fit the item, we must take it regardless of quality.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 6. Progressive Compression:
    // Towards the end of the stream, prioritize filling existing bins aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (bin_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize new bin creation heavily early on, but allow flexibility as the stream ends
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress) * 50.0 + (open_bins_count as f64 * 2.5)
    } else {
        0.0
    };

    // Best-fit objective: prioritize smaller post_residual (tighter packing)
    let mut score = post_residual as f64;

    // Penalty for leaving a bin in a state that is hard to fill (the "dead zone" 1-9)
    // We penalize post_residuals that are small but non-zero, as they are unlikely to fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead coupling: if the next item is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we effectively "kill" the bin for the next step.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Encourage balancing residuals across open bins to prevent isolated high-residual bins
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // Apply the computed new_bin_penalty
    score += new_bin_penalty;

    // Final scaling: favor bins that are already open to keep the number of active bins minimal
    if !is_new_bin {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

