pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize tiny residuals that are unlikely to accommodate future items (1..9).
    // Small gaps (1-9) are "poisoned" space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64).sqrt();
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 3. Bin Pressure: If this is the only bin that can fit the item, prioritize it to prevent opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 4. Global Density: If we have many open bins, penalize creating new ones or keeping bins with high residuals.
    let density_penalty = (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);
    score += density_penalty * 10.0;

    // 5. New Bin Logic: If considering a new bin, make it expensive unless necessary.
    if bin_residual == bin_capacity {
        // High base cost to open new bin, reduced by total items progress (end of stream = lower penalty).
        let progress = step_index as f64 / total_items as f64;
        score = 45.0 - (progress * 15.0);

        // If many bins are already open, strongly discourage opening another.
        if open_bins_count > 5 {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize smaller post-residual (Best Fit)
    let mut score = post;

    // Penalty for creating "dead space": small residuals that are hard to fill
    // We define "dead" as < 10 (since min item size is 10 in typical scenarios)
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (1.0 - (post / 10.0));
    }

    // Dynamic Lookahead Coupling:
    // If next_item_size is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the current choice
    // to preserve space for the upcoming item.
    if next_item_size > 0 {
        let fit_penalty = if post < next_item_size as f64 {
            (next_item_size as f64 - post) * 0.5
        } else {
            0.0
        };
        score += fit_penalty * (1.0 - progress);
    }

    // Stream progression weight: 
    // Towards the end of the stream, we become more aggressive in packing tightly
    // to avoid leaving too many bins partially filled.
    let packing_pressure = progress.powf(2.0) * 15.0;
    score += packing_pressure * (post / bin_capacity as f64);

    // If this is the only bin that fits, reduce the penalty to prevent 
    // unnecessary new bin allocation unless the fit is extremely poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New bin logic:
    // If bin_residual == bin_capacity, it's a new bin. 
    // Only choose it if the penalty of filling an existing bin is higher than this threshold.
    if bin_residual == bin_capacity {
        score = 12.0 + (progress * 8.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize "sliver" waste (small remaining gaps).
    // If post_residual is very small (1-9), it often traps space that cannot be used.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 3. Global Efficiency: If many bins are open, favor filling them to reduce fragmentation.
    // If few bins are open, be more selective to save space for future items.
    if open_bins_count > 0 {
        score += (open_bins_count as f64) * 2.0 * (1.0 - progress);
    }

    // 4. Critical Threshold Management: If this is the last chance for the current item, 
    // prioritize fitting it over opening a new bin (unless the fit is extremely poor).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // 5. New Bin Logic: If evaluating a new bin (bin_residual == bin_capacity), 
    // only choose it if it's impossible to fit in existing bins efficiently.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Only open a new bin if the current mean_residual is already very low
            // suggesting existing bins are too full to accommodate future variance.
            score = 15.0 + (mean_residual * 0.5) + (progress * 10.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // 1. Base penalty: The remaining space (Best Fit approach).
    let mut score = post_residual as f64;

    // 2. Harmonic Class Logic:
    // We penalize residuals that are small but not zero (fragmentation),
    // especially if they cannot fit the next item.
    if post_residual > 0 && next_item_size > 0 {
        if post_residual < next_item_size {
            // High penalty for creating 'unusable' space for the immediate next item.
            score += 45.0;
        } else {
            // Reward for creating a residual that fits the next item perfectly (or nearly so).
            score -= (100.0 / (1.0 + (post_residual - next_item_size) as f64)).min(20.0);
        }
    }

    // 3. New Bin Thresholding:
    // If this is an empty bin, calculate the cost of opening it.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current open bins are all very tight (high fragmentation).
        // If fitting_bins_count is low, we are forced into a bad bin, so discourage new bin creation.
        let openness_penalty = (open_bins_count as f64) * 2.5;
        let fragmentation_relief = (100.0 - mean_residual) * 0.4;
        score = 25.0 + openness_penalty - fragmentation_relief;
    } else {
        // 4. Harmonic Density:
        // Penalize bins that create 'middle-range' residuals (30-60) which are hard to fill.
        if post_residual > 30 && post_residual < 60 {
            score += 15.0;
        }

        // Reward filling to near-capacity (Best Fit Decreasing style behavior).
        if post_residual < 10 {
            score -= 20.0;
        }
    }

    // 5. Progression scaling:
    // Towards the end of the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}
